-- Reconcile requested leasing copy against the 16 October source review.
-- Exact-text replacements preserve later CMS edits and all unrelated fields.
-- Dynamic comparison facts remain derived from the current published listings.

UPDATE "BlogPost" SET "contentHtml" = replace("contentHtml", $before0$<p>As a general guide: older or lower-spec industrial buildings often sit around 6&ndash;8 metres, which limits racking to two or three levels. Modern logistics and distribution facilities are typically built from 9&ndash;12 metres upward, supporting higher-bay racking and significantly more storage volume per square metre of floor space. If vertical storage density matters to your operation, eave height is worth confirming before anything else on this list &mdash; a warehouse with the right floor area but the wrong eave height can still be a poor fit.</p>$before0$, $after0$<p>Eaves, usable clear height and racking capacity are different measurements. Check the lowest obstruction, handling equipment, floor loading and fire design with the relevant specialists before choosing a racking layout; do not infer a permitted number of storage levels from a height figure alone.</p>$after0$), "updatedAt" = CURRENT_TIMESTAMP
WHERE "slug" = $slug$warehouse-checklist-midrand-eave-height-loading-yard-space$slug$ AND strpos("contentHtml", $before0$<p>As a general guide: older or lower-spec industrial buildings often sit around 6&ndash;8 metres, which limits racking to two or three levels. Modern logistics and distribution facilities are typically built from 9&ndash;12 metres upward, supporting higher-bay racking and significantly more storage volume per square metre of floor space. If vertical storage density matters to your operation, eave height is worth confirming before anything else on this list &mdash; a warehouse with the right floor area but the wrong eave height can still be a poor fit.</p>$before0$) > 0;

UPDATE "BlogPost" SET "contentHtml" = replace("contentHtml", $before1$<p>Note: Midpoint's current listings &mdash; 1 Kingfisher Avenue, 2 Kingfisher Avenue, Unit 2 at 6 Kingfisher Avenue, and 6 Weaver Avenue &mdash; do not yet have published eave heights. Confirm with the leasing team before relying on a specific figure for any unit.</p>$before1$, $after1$<p>Where available, individual listings now publish height to eaves or clearance. Check the <a href="/warehouses#compare-spaces">current unit specification comparison</a> and its linked source listings. These measurements are not interchangeable: confirm usable height below obstructions and whether the advertised specification describes current or proposed works.</p>$after1$), "updatedAt" = CURRENT_TIMESTAMP
WHERE "slug" = $slug$warehouse-checklist-midrand-eave-height-loading-yard-space$slug$ AND strpos("contentHtml", $before1$<p>Note: Midpoint's current listings &mdash; 1 Kingfisher Avenue, 2 Kingfisher Avenue, Unit 2 at 6 Kingfisher Avenue, and 6 Weaver Avenue &mdash; do not yet have published eave heights. Confirm with the leasing team before relying on a specific figure for any unit.</p>$before1$) > 0;

UPDATE "BlogPost" SET "contentHtml" = replace("contentHtml", $before2$<p>Note: the exact number and type of loading points per Midpoint building aren't yet published &mdash; the existing warehouse pillar confirms dock levellers and on-grade roller shutters are present across the estate generally, but per-building counts need confirming with the leasing team.</p>$before2$, $after2$<p>The warehouse guide explains loading configurations to assess; it does not establish that every building has dock levellers or on-grade loading. Request the number, type and dimensions of loading points for the selected unit, together with the approach, staging and vehicle circulation plan.</p>$after2$), "updatedAt" = CURRENT_TIMESTAMP
WHERE "slug" = $slug$warehouse-checklist-midrand-eave-height-loading-yard-space$slug$ AND strpos("contentHtml", $before2$<p>Note: the exact number and type of loading points per Midpoint building aren't yet published &mdash; the existing warehouse pillar confirms dock levellers and on-grade roller shutters are present across the estate generally, but per-building counts need confirming with the leasing team.</p>$before2$) > 0;

UPDATE "BlogPost" SET "contentHtml" = replace("contentHtml", $before3$<p>Note: yard dimensions per Midpoint building aren't currently published. This is one of the two biggest specification gaps flagged on the warehouses pillar and worth prioritising alongside eave height.</p>$before3$, $after3$<p>A published yard area can be found in some individual descriptions and the <a href="/warehouses#compare-spaces">live warehouse comparison</a>. Area does not establish yard depth, usable shape, door approach or truck turning geometry. Request a dimensioned plan and test the intended vehicles for the specific property.</p>$after3$), "updatedAt" = CURRENT_TIMESTAMP
WHERE "slug" = $slug$warehouse-checklist-midrand-eave-height-loading-yard-space$slug$ AND strpos("contentHtml", $before3$<p>Note: yard dimensions per Midpoint building aren't currently published. This is one of the two biggest specification gaps flagged on the warehouses pillar and worth prioritising alongside eave height.</p>$before3$) > 0;

UPDATE "BlogPost" SET "contentHtml" = replace("contentHtml", $before4$<p>Midpoint's estate runs on generator-backed power. Note: specific kVA capacity per building, and whether backup coverage extends to warehouse floor equipment or is limited to office and common areas, aren't currently published per unit &mdash; confirm with the leasing team before assuming either way.</p>$before4$, $after4$<p>Individual listing descriptions may publish a power figure in MVA or kVA; the <a href="/warehouses#compare-spaces">current specification comparison</a> keeps that figure attached to its source unit. A power figure does not establish the generator rating, allocated tenant load, changeover time or circuits supported. Confirm the supply and backup arrangements against your equipment schedule before relying on them.</p>$after4$), "updatedAt" = CURRENT_TIMESTAMP
WHERE "slug" = $slug$warehouse-checklist-midrand-eave-height-loading-yard-space$slug$ AND strpos("contentHtml", $before4$<p>Midpoint's estate runs on generator-backed power. Note: specific kVA capacity per building, and whether backup coverage extends to warehouse floor equipment or is limited to office and common areas, aren't currently published per unit &mdash; confirm with the leasing team before assuming either way.</p>$before4$) > 0;

UPDATE "BlogPost" SET "contentHtml" = replace("contentHtml", $before5$<p>Most warehouse tenants need some office space attached &mdash; for site management, reception, or admin staff &mdash; rather than running the whole operation off the warehouse floor. Check how much integrated office space is included, whether it's air-conditioned separately from the warehouse, and whether it's sized appropriately for your on-site team. Several Midpoint facilities include integrated office components as standard; exact office GLA per building should be confirmed with the leasing team before quoting a specific figure.</p>$before5$, $after5$<p>Warehouse operations may need offices for reception, administration, dispatch or supervision. Some current listing descriptions publish an office component alongside warehouse area; compare the <a href="/warehouses#compare-spaces">source-linked unit breakdown</a> rather than assuming no office areas are published. Confirm the measured areas, fit-out, air-conditioning, staff facilities and office-to-warehouse ratio on the current floor plan for the selected unit.</p>$after5$), "updatedAt" = CURRENT_TIMESTAMP
WHERE "slug" = $slug$warehouse-checklist-midrand-eave-height-loading-yard-space$slug$ AND strpos("contentHtml", $before5$<p>Most warehouse tenants need some office space attached &mdash; for site management, reception, or admin staff &mdash; rather than running the whole operation off the warehouse floor. Check how much integrated office space is included, whether it's air-conditioned separately from the warehouse, and whether it's sized appropriately for your on-site team. Several Midpoint facilities include integrated office components as standard; exact office GLA per building should be confirmed with the leasing team before quoting a specific figure.</p>$before5$) > 0;

UPDATE "BlogPost" SET "contentHtml" = replace("contentHtml", $before6$<p>See current availability at <a href="https://mid-point.co.za/warehouses">Midpoint</a>, or check the live vacancy schedule <a href="https://mid-point.co.za/availability-report">here</a>, for up-to-date sizes and dates. For the specification detail flagged above &mdash; eave height, loading configuration, yard dimensions and power capacity &mdash; contact the leasing team directly; this is exactly the kind of detail worth confirming per building rather than assuming from a general listing.</p>$before6$, $after6$<p>Use the <a href="/warehouses#compare-spaces">current warehouse comparison and published specifications</a>, or open the <a href="/vacancies?sector=Warehouse">warehouse vacancy schedule</a>, for unit sizes, asking rates and advertised availability. Read the linked property details, then <a href="/contact-us?interest=Warehouse%20space#Contact">request a floor plan and viewing</a> to confirm current condition, loading, yard geometry, power and permitted use.</p>$after6$), "updatedAt" = CURRENT_TIMESTAMP
WHERE "slug" = $slug$warehouse-checklist-midrand-eave-height-loading-yard-space$slug$ AND strpos("contentHtml", $before6$<p>See current availability at <a href="https://mid-point.co.za/warehouses">Midpoint</a>, or check the live vacancy schedule <a href="https://mid-point.co.za/availability-report">here</a>, for up-to-date sizes and dates. For the specification detail flagged above &mdash; eave height, loading configuration, yard dimensions and power capacity &mdash; contact the leasing team directly; this is exactly the kind of detail worth confirming per building rather than assuming from a general listing.</p>$before6$) > 0;

UPDATE "PillarPage" SET "heroAnswer" = $next$Compare offices to rent at Midpoint in Halfway House, Midrand. Review each published area, asking rate and availability, then arrange a viewing. Confirm backup coverage, parking, amenities, occupation timing and complete costs for your chosen suite.$next$, "updatedAt" = CURRENT_TIMESTAMP
