WHERE "slug" = $slug$offices$slug$ AND "seoDescription" = $previous$Modern offices to rent in Midrand at Midpoint, between Johannesburg and Pretoria. View live availability and arrange a viewing.$previous$;

UPDATE "PillarPage" SET "heroAnswer" = $next$Compare warehouse and conversion opportunities at Midpoint in Halfway House, Midrand. Review current published areas, asking rates, availability and unit-specific specifications. Match the property to your loading, yard, office, power and occupation requirements, and confirm the current condition and any proposed works.$next$, "updatedAt" = CURRENT_TIMESTAMP
WHERE "slug" = $slug$warehouses$slug$ AND "heroAnswer" = $previous$Midpoint offers warehouse space to rent in Midrand for logistics, distribution, storage and adaptable industrial operations. The estate combines access to the Johannesburg–Pretoria corridor with practical loading, yard, power and office configurations. Available buildings vary, so tenants should compare each unit against their vehicle movements, storage system, power demand, staffing and future growth plans.$previous$;

UPDATE "PillarPage" SET "seoDescription" = $next$Compare Midpoint warehouses to rent in Midrand: published specifications, areas, asking rates, indicative monthly base rentals and availability. Book a viewing.$next$, "updatedAt" = CURRENT_TIMESTAMP
WHERE "slug" = $slug$warehouses$slug$ AND "seoDescription" = $previous$Compare warehouses to rent in Midrand at Midpoint: location, clear height, loading, yards, power and live availability. Arrange a site inspection.$previous$;

UPDATE "PillarPage" SET "features" = jsonb_set("features", '{0,text}', to_jsonb($feature$Conventional offices vary in size, layout and condition. Compare the published unit descriptions and photographs, then request the current floor plan. Confirm the existing partitions, kitchens, air-conditioning, reception, fit-out responsibilities and occupation programme for the specific suite.$feature$::text)), "updatedAt" = CURRENT_TIMESTAMP
WHERE "slug" = 'offices' AND "features"->0->>'text' = $previousfeature$Office suites across the estate vary in size and configuration, allowing businesses to scale as their needs evolve. Some offices are newly refurbished or redeveloped, while others provide larger floorplates suited to corporate teams, professional services firms, and operational headquarters. Layouts incorporate features such as private reception areas, dedicated kitchens, modern HVAC systems, and secure access control, creating professional working environments that balance practicality with comfort.$previousfeature$;
